SELECT ss.product_id, QUARTER(ss.sale_date) AS sale_quarter, ROUND(STDDEV(i.quantity), 2) AS stddev_quantity, MIN(i.quantity) AS min_quantity FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.units != 19 GROUP BY ss.product_id, QUARTER(ss.sale_date) HAVING min_quantity >= 100 ORDER BY stddev_quantity DESC, ss.product_id DESC, sale_quarter LIMIT 1;
